import{_ as t,o as s,c as e,a5 as n}from"./chunks/framework.C1a7WKBV.js";const u=JSON.parse('{"title":"提示词入门","description":"掌握写好提示词的四个基本动作，显著提升 AI 回答质量。","frontmatter":{"title":"提示词入门","description":"掌握写好提示词的四个基本动作，显著提升 AI 回答质量。"},"headers":[],"relativePath":"concepts/prompt-basics.md","filePath":"concepts/prompt-basics.md","lastUpdated":1788838685000}'),p={name:"concepts/prompt-basics.md"};function o(i,a,l,d,r,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="提示词入门" tabindex="-1">提示词入门 <a class="header-anchor" href="#提示词入门" aria-label="Permalink to &quot;提示词入门&quot;">​</a></h1><p>提示词（Prompt）就是你发给 AI 的那段话。同一个模型，提问方式不同，回答质量可能天差地别。好消息是：写好提示词不需要&quot;咒语&quot;，只需要几个基本动作。</p><h2 id="_1-核心认知-ai-不会读心" tabindex="-1">1. 核心认知：AI 不会读心 <a class="header-anchor" href="#_1-核心认知-ai-不会读心" aria-label="Permalink to &quot;1. 核心认知：AI 不会读心&quot;">​</a></h2><p>模型只根据你提供的文字作答。你没写的约束，它就不知道；你写得含糊，它就只能猜。所以提示词的第一原则是：</p><blockquote><p>把 AI 当成一个<strong>能力很强、但对你的处境一无所知的新同事</strong>。交代任务时，把你对人类同事会说的背景都告诉它。</p></blockquote><h2 id="_2-四个基本动作" tabindex="-1">2. 四个基本动作 <a class="header-anchor" href="#_2-四个基本动作" aria-label="Permalink to &quot;2. 四个基本动作&quot;">​</a></h2><h3 id="_2-1-给清晰的任务-做什么" tabindex="-1">2.1 给清晰的任务（做什么） <a class="header-anchor" href="#_2-1-给清晰的任务-做什么" aria-label="Permalink to &quot;2.1 给清晰的任务（做什么）&quot;">​</a></h3><p>把&quot;要什么&quot;说具体，最好包含格式和范围。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ 帮我写个介绍 AI 的东西。</span></span>
<span class="line"><span>✅ 写一段 150 字以内的产品介绍，主题是&quot;AI 面试练习工具&quot;，目标读者是应届毕业生，语气友好、避免夸大。</span></span></code></pre></div><h3 id="_2-2-给上下文-背景是什么" tabindex="-1">2.2 给上下文（背景是什么） <a class="header-anchor" href="#_2-2-给上下文-背景是什么" aria-label="Permalink to &quot;2.2 给上下文（背景是什么）&quot;">​</a></h3><p>相关的背景信息直接贴进对话：给谁看、用在什么场合、已经有什么。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ 这段文案有问题吗？</span></span>
<span class="line"><span>✅ 这段文案用于 app 首页，目标用户是不懂技术的中小企业主。</span></span>
<span class="line"><span>   【粘贴文案】</span></span>
<span class="line"><span>   请检查是否有技术黑话会让这类用户困惑，并指出具体句子。</span></span></code></pre></div><h3 id="_2-3-给示例-长什么样" tabindex="-1">2.3 给示例（长什么样） <a class="header-anchor" href="#_2-3-给示例-长什么样" aria-label="Permalink to &quot;2.3 给示例（长什么样）&quot;">​</a></h3><p>给一个你期望的输出样例（few-shot），模型的模仿能力远强于理解抽象描述的能力。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请按下面的格式输出每条数据：</span></span>
<span class="line"><span>{&quot;城市&quot;: &quot;上海&quot;, &quot;气温&quot;: &quot;28°C&quot;, &quot;建议&quot;: &quot;适合轻薄外套&quot;}</span></span></code></pre></div><h3 id="_2-4-给角色-以什么身份答" tabindex="-1">2.4 给角色（以什么身份答） <a class="header-anchor" href="#_2-4-给角色-以什么身份答" aria-label="Permalink to &quot;2.4 给角色（以什么身份答）&quot;">​</a></h3><p>让模型先站定位置，回答的专业度和语气都会更贴合。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一位有十年经验的植物学编辑。</span></span>
<span class="line"><span>请审校这篇多肉植物养护指南中的事实性错误。</span></span></code></pre></div><h2 id="_3-迭代-第一次不满意是常态" tabindex="-1">3. 迭代：第一次不满意是常态 <a class="header-anchor" href="#_3-迭代-第一次不满意是常态" aria-label="Permalink to &quot;3. 迭代：第一次不满意是常态&quot;">​</a></h2><p>提示词不是一次性写作，而是一轮对话。回复不理想时，比起重写整个提示词，更高效的是<strong>指出差距</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;太长了，压缩到 100 字以内，删掉背景介绍。&quot;</span></span>
<span class="line"><span>&quot;语气太正式了，像跟朋友聊天那样重写。&quot;</span></span>
<span class="line"><span>&quot;第 2 点展开讲，其他的保持不变。&quot;</span></span></code></pre></div><p>一个实用的迭代句式是：<strong>&quot;保持 X 不变，只修改 Y&quot;</strong>——它能防止模型把你满意的部分也重写掉。</p><h2 id="_4-让-ai-帮你写提示词" tabindex="-1">4. 让 AI 帮你写提示词 <a class="header-anchor" href="#_4-让-ai-帮你写提示词" aria-label="Permalink to &quot;4. 让 AI 帮你写提示词&quot;">​</a></h2><p>提示词本身就是 AI 擅长的任务。当你的需求很复杂时，可以反过来让 AI 提问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想让你帮我做一份周报总结。在开始之前，</span></span>
<span class="line"><span>请先问我 3~5 个你需要了解的问题，然后再输出结果。</span></span></code></pre></div><p>这种方式（有时叫&quot;反问式提示&quot;）特别适合需求还模糊的任务，比自己憋一个完美提示词快得多。</p><h2 id="_5-常见误区" tabindex="-1">5. 常见误区 <a class="header-anchor" href="#_5-常见误区" aria-label="Permalink to &quot;5. 常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>更好的做法</th></tr></thead><tbody><tr><td>一句话甩需求，指望它猜</td><td>前面三要素给全：任务、上下文、格式</td></tr><tr><td>要求&quot;写得好一点&quot;这种模糊修饰</td><td>给出可判定的标准：字数、受众、禁用词</td></tr><tr><td>一次塞十件事</td><td>拆步骤，一步一步来，每步确认后再进行</td></tr><tr><td>回答错了就重开对话</td><td>直接指出哪里错了，让它修正</td></tr><tr><td>把关键信息留在&quot;上一轮对话&quot;</td><td>重要约束在每次任务开头重申</td></tr></tbody></table><p>掌握了这些，你就完成了 AI 协作的第一步。下一步是让 AI 从&quot;动嘴&quot;走向&quot;动手&quot;——那就是《<a href="/ai-handbook/concepts/agent-and-mcp">Agent 与 MCP</a>》的主题。</p><p>要把这些动作用到编程交付场景（需求模板、先方案后实现、修复循环），继续读《<a href="/ai-handbook/tips/prompt-secrets">Prompt 提示词秘籍</a>》。用到没见过的术语，随手查《<a href="/ai-handbook/concepts/glossary">AI 术语速查表</a>》。</p>`,30)])])}const b=t(p,[["render",o]]);export{u as __pageData,b as default};
